<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useQuery } from '@tanstack/vue-query'
import { Search, Plus, Refresh, Download } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, type Model } from '../api/client'
import { useSession } from '../stores/session'
import { useAction } from '../composables/useAction'
import PageHeader from '../components/PageHeader.vue'
import DataTable from '../components/DataTable.vue'
import StatusTag from '../components/StatusTag.vue'
import InvoiceDetail from '../components/InvoiceDetail.vue'
const session=useSession(),route=useRoute(),router=useRouter(),{busy,run}=useAction()
const posting=computed(()=>route.path==='/posting'),q=ref(String(route.query.q||'')),status=ref(String(route.query.status||'')),period=ref(String(route.query.period||'2026-11')),page=ref(Number(route.query.page)||1),selected=ref<Model<'Invoice'>[]>([]),selectedId=ref(''),table=ref<{clearSelection:()=>void}>()
const importOpen=ref(route.query.import==='1'),number=ref('DEMO-IMPORT-001'),partner=ref('青禾信息技术（演示）')
const filters=computed(()=>({q:q.value,status:posting.value?'pending_posting':status.value,period:period.value||'',page:page.value,page_size:20}))
const list=useQuery({queryKey:computed(()=>['invoices',session.tenant,filters.value]),queryFn:()=>api('/invoices','get',{tenant:session.tenant,params:filters.value})})
const detailId=computed(()=>posting.value?selectedId.value:String(route.params.id||''))
watch([q,status,period],()=>{page.value=1})
watch(filters,()=>{selected.value=[];table.value?.clearSelection();void router.replace({path:route.path,query:{q:q.value||undefined,status:status.value||undefined,period:period.value||undefined,page:page.value>1?page.value:undefined}})})
watch(()=>list.data.value?.page,value=>{if(value&&value!==page.value)page.value=value})
watch(()=>list.data.value,()=>{selected.value=[];table.value?.clearSelection()})
function open(row:Model<'Invoice'>){if(posting.value)selectedId.value=row.id;else void router.push({path:`/invoices/${row.id}`,query:route.query})}
function close(){if(posting.value)selectedId.value='';else void router.push({path:'/invoices',query:route.query})}
function reset(){q.value='';status.value='';period.value='';page.value=1}
async function importInvoice(){await run(`import:${number.value}`,async key=>{const invoice=await api('/invoices','post',{tenant:session.tenant,body:{number:number.value,partner:partner.value},key});importOpen.value=false;open(invoice)},'样例发票已采集')}
function selectable(row:Model<'Invoice'>){return !!row.suggestion&&row.suggestion.confidence>=0.95&&!row.suggestion.need_review&&session.can('posting:write')}
async function batch(){try{await ElMessageBox.confirm(`将采纳 ${selected.value.length} 条高置信度建议并生成演示凭证。`,'批量采纳确认',{confirmButtonText:'确认采纳',cancelButtonText:'取消'})}catch{return}await run('batch',async key=>{const result=await api('/suggestions/batch-accept','post',{tenant:session.tenant,body:{ids:selected.value.map(r=>r.suggestion?.id)},key});ElMessage.info(`成功 ${result.processed.length} 条，跳过 ${result.skipped.length} 条`);selected.value=[]},'批量处理完成')}
function exportRows(){const rows=list.data.value?.items||[];const escape=(value:string)=>`"${value.replaceAll('"','""')}"`;const csv='\uFEFF'+[['样例票号','交易对方','日期','金额','税额','价税合计','状态'],...rows.map(r=>[r.number,r.partner,r.date,r.amount,r.tax,r.total,r.status])].map(r=>r.map(v=>escape(/^[=+\-@]/.test(v)?`'${v}`:v)).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='税枢云-当前页演示发票.csv';a.click();URL.revokeObjectURL(url)}
</script>
<template><div><PageHeader :title="posting?'智能入账':'发票中心'" :description="posting?'核对建议与依据，让每一笔入账有据可循。':'统一管理进销项发票，从采集到入账全程可追溯。'"><el-button v-if="!posting" :icon="Download" :disabled="!list.data.value?.items.length" @click="exportRows">导出当前页</el-button><el-button v-if="!posting&&session.can('invoice:write')" type="primary" :icon="Plus" @click="importOpen=true">模拟导入发票</el-button><el-button v-if="posting&&session.can('posting:write')" type="primary" :disabled="!selected.length" :loading="busy" @click="batch">批量采纳{{selected.length?`（${selected.length}）`:''}}</el-button></PageHeader><div v-if="posting" class="posting-banner"><span>✧</span><div><strong>建议有依据，入账更安心</strong><p>置信度 ≥ 95% 且无需人工复核的建议支持批量采纳，其余请逐条确认。</p></div><span class="demo-label">演示建议</span></div><section class="panel invoice-panel"><div class="list-tabs"><button :class="{active:!status}" @click="status=''">{{posting?'待入账队列':'全部发票'}}<span>{{list.data.value?.total??'—'}}</span></button><template v-if="!posting"><button :class="{active:status==='pending_posting'}" @click="status='pending_posting'">待入账</button><button :class="{active:status==='posted'}" @click="status='posted'">已入账</button><button :class="{active:status==='verify_failed'}" @click="status='verify_failed'">异常发票</button></template></div><div class="filter-bar"><el-input v-model="q" :prefix-icon="Search" clearable placeholder="搜索演示票号 / 交易对方" aria-label="搜索演示票号或交易对方"/><el-select v-if="!posting" v-model="status" placeholder="全部状态" clearable aria-label="发票状态"><el-option v-for="(label,value) in {collected:'已采集',verifying:'查验中',verified:'查验通过',verify_failed:'查验异常',pending_posting:'待入账',posted:'已入账',archived:'已归档',voided:'已作废',red_flushed:'已红冲'}" :key="value" :value="value" :label="label"/></el-select><el-date-picker v-model="period" type="month" value-format="YYYY-MM" placeholder="所有期间" aria-label="开票期间"/><el-button @click="reset">重置</el-button><el-button :icon="Refresh" circle aria-label="刷新列表" @click="list.refetch()"/></div><DataTable :loading="list.isFetching.value" :error="list.error.value" :total="list.data.value?.total||0" :page="page" @page="page=$event" @retry="list.refetch()"><el-table ref="table" :data="list.data.value?.items||[]" row-key="id" @selection-change="selected=$event" :empty-text="q||status||period?'没有符合筛选条件的发票，可尝试重置筛选':'暂无发票，请模拟导入第一张样例票据'"><el-table-column v-if="posting" type="selection" width="45" :selectable="selectable"/><el-table-column label="发票信息" min-width="225"><template #default="{row}"><button class="table-link" @click="open(row)">{{row.number}}</button><div class="table-subtext">{{row.kind}}<span>·</span>{{row.direction}}</div></template></el-table-column><el-table-column label="交易对方" prop="partner" min-width="200"/><el-table-column v-if="!posting" label="开票日期" prop="date" width="120"/><el-table-column v-if="!posting" label="不含税金额" prop="amount" align="right" width="125"/><el-table-column v-if="!posting" label="税额" prop="tax" align="right" width="100"/><el-table-column label="价税合计" align="right" width="135"><template #default="{row}"><span class="money">¥ {{row.total}}</span></template></el-table-column><el-table-column v-if="posting" label="建议科目" min-width="210"><template #default="{row}">{{row.suggestion?.account||'—'}}</template></el-table-column><el-table-column v-if="posting" label="置信度" width="135"><template #default="{row}"><strong>{{row.suggestion?(row.suggestion.confidence*100).toFixed(0)+'%':'—'}}</strong><div class="table-subtext" :class="{'warning-text':row.suggestion?.need_review}">{{row.suggestion?.need_review?'需人工复核':'可批量采纳'}}</div></template></el-table-column><el-table-column label="处理状态" width="110"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column label="操作" fixed="right" width="85"><template #default="{row}"><el-button link type="primary" @click="open(row)">{{posting?'查看建议':'查看详情'}}</el-button></template></el-table-column></el-table></DataTable></section><p class="page-note">演示环境 · 所有票据均为合成样例，状态由本地模拟服务保存。</p><InvoiceDetail v-if="detailId" :id="detailId" @close="close"/><el-dialog v-model="importOpen" title="模拟采集发票" width="min(500px,95vw)"><el-alert title="导入固定金额的合成样例，用于体验查验与入账流程。" type="info" :closable="false"/><form class="import-form" @submit.prevent="importInvoice"><label for="invoice-number">样例票号</label><el-input id="invoice-number" v-model="number" placeholder="DEMO-IMPORT-001" maxlength="45"/><label for="partner">交易对方</label><el-input id="partner" v-model="partner" maxlength="80"/><p>再次导入相同票号将展示重复提示。样例金额 ¥ 1,200.00，税额 ¥ 72.00，价税合计 ¥ 1,272.00。</p><el-button native-type="submit" type="primary" :loading="busy" :disabled="!number.trim()||!partner.trim()">确认模拟导入</el-button></form></el-dialog></div></template>

